/bin/bash -lc "python - <<'PY'
from pathlib import Path
acc=[]; don=[]
for p, arr in [('/workspace/results/osa_predict_run1/SpliceAI_5000_10000/acceptor_predictions.bed', acc),('/workspace/results/osa_predict_run1/SpliceAI_5000_10000/donor_predictions.bed', don)]:
    for line in Path(p).read_text().splitlines():
        if not line.strip():
            continue
        f=line.split('\\t')
        if float(f[4]) >= 0.9:
            arr.append((int(f[1]), int(f[2]), float(f[4]), f[5]))
# transcript order for minus strand is descending genomic coordinate.
events=[]
for x in acc: events.append(('A', x[0], x[1], x[2]))
for x in don: events.append(('D', x[0], x[1], x[2]))
events=sorted(events, key=lambda e: e[1], reverse=True)
pairs=[]
for i,e in enumerate(events):
    if e[0]=='A':
        nxt=next((x for x in events[i+1:] if x[0]=='D'), None)
        if nxt:
            pairs.append((e,nxt))
print('events', ' '.join(f'{t}{s}' for t,s,_,_ in events))
print('acceptors', len(acc), 'donors', len(don), 'internal_pairs', len(pairs), 'terminal_exons', 2, 'total_exons', len(pairs)+2)
PY"
